class MNode {
  prev: MNode | null = null;
  next: MNode | null = null;
  child: MNode | null = null;
  constructor(public val: number) {}
}

function flattenValues(list: any): number[] {
  const build = (lst: any[] | null): MNode | null => {
    let head: MNode | null = null, tail: MNode | null = null;
    for (const [val, child] of lst || []) {
      const node = new MNode(val);
      node.child = build(child);
      if (tail) { tail.next = node; node.prev = tail; } else head = node;
      tail = node;
    }
    return head;
  };
  const head = build(list);
  const later: MNode[] = [];
  let cur = head;
  while (cur) {
    if (cur.child) {
      if (cur.next) later.push(cur.next);
      cur.next = cur.child;
      cur.child.prev = cur;
      cur.child = null;
    } else if (!cur.next && later.length) {
      const nxt = later.pop()!;
      cur.next = nxt;
      nxt.prev = cur;
    }
    cur = cur.next;
  }
  const out: number[] = [];
  for (let n = head; n; n = n.next) out.push(n.val);
  return out;
}

