        def build(lst):
            head = tail = None
            for val, child in lst or []:
                node = MNode(val)
                node.child = build(child)
                if tail:
                    tail.next, node.prev = node, tail
                else:
                    head = node
                tail = node
            return head

        head = build(list)
        later = []
        cur = head
        while cur:
            if cur.child:
                if cur.next:
                    later.append(cur.next)
                cur.next, cur.child.prev = cur.child, cur
                cur.child = None
            elif not cur.next and later:
                nxt = later.pop()
                cur.next, nxt.prev = nxt, cur
            cur = cur.next
        out = []
        n = head
        while n:
            out.append(n.val)
            n = n.next
        return out

